<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Auto‑Snake</title>
<style>
    body{
        margin:0;
        background:#111;
        overflow:hidden;
        color:#0f0;
        font-family:sans-serif;
    }
    #game{
        background:#000;
        display:block;
        margin:auto;
    }
    #score{
        position:absolute;
        top:10px;
        left:10px;
        color:#0f0;
        font-size:18px;
    }
</style>
</head>
<body>
<canvas id="game" width="400" height="400"></canvas>
<div id="score">Score: 0</div>
<script>
(() => {
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const scoreEl = document.getElementById('score');

    const cols = 20, rows = 20;
    const cellSize = canvas.width / cols;

    // snake state
    let snake = [{x: 10, y: 10}];
    let dir = {x: 0, y: -1}; // start moving up
    let food = randomCell();
    let score = 0;
    const speed = 100; // ms per tick

    function randomCell(){
        return {
            x: Math.floor(Math.random()*cols),
            y: Math.floor(Math.random()*rows)
        };
    }

    function drawCell(x, y, color){
        ctx.fillStyle = color;
        ctx.fillRect(x*cellSize, y*cellSize, cellSize-1, cellSize-1);
    }

    function updateDirection(){
        const head = snake[0];
        // simple greedy AI: move in axis that reduces Manhattan distance
        if (head.x < food.x && dir.x !== -1) {
            dir = {x: 1, y: 0};
        } else if (head.x > food.x && dir.x !== 1) {
            dir = {x: -1, y: 0};
        } else if (head.y < food.y && dir.y !== -1) {
            dir = {x: 0, y: 1};
        } else if (head.y > food.y && dir.y !== 1) {
            dir = {x: 0, y: -1};
        }
        // if already aligned on one axis, allow turn on the other axis
    }

    function step(){
        updateDirection();

        // compute new head position with wrap‑around
        const newHead = {
            x: (snake[0].x + dir.x + cols) % cols,
            y: (snake[0].y + dir.y + rows) % rows
        };

        // check self‑collision (optional: end game)
        for (let part of snake) {
            if (part.x === newHead.x && part.y === newHead.y) {
                // restart
                snake = [{x:10,y:10}];
                dir = {x:0,y:-1};
                score = 0;
                scoreEl.textContent = 'Score: 0';
                food = randomCell();
                return;
            }
        }

        snake.unshift(newHead);

        // eat food?
        if (newHead.x === food.x && newHead.y === food.y){
            score++;
            scoreEl.textContent = 'Score: ' + score;
            food = randomCell();
        } else {
            snake.pop(); // move without growing
        }
    }

    function render(){
        ctx.clearRect(0,0,canvas.width,canvas.height);
        // draw food
        drawCell(food.x, food.y, '#f00');
        // draw snake
        snake.forEach((seg,i)=>drawCell(seg.x, seg.y, '#0f0'));
    }

    function loop(){
        step();
        render();
        setTimeout(loop, speed);
    }

    // start
    loop();
})();
</script>
</body>
</html>
```

The script repeatedly moves the snake one cell toward the food using a simple greedy AI, grows it when it reaches the food, and updates the displayed score.
